class Solution {
public:
    vector<string> restoreIpAddresses(string s) {
        vector<string> res;
        vector<string> parts;
        auto backtrack = [&](auto& self, int start) -> void {
            if (parts.size() == 4) {
                if (start == (int)s.size()) {
                    res.push_back(parts[0] + "." + parts[1] + "." + parts[2] + "." + parts[3]);
                }
                return;
            }
            for (int len = 1; len <= 3; len++) {
                if (start + len > (int)s.size()) break;
                string seg = s.substr(start, len);
                if (seg.size() > 1 && seg[0] == '0') continue;
                if (stoi(seg) <= 255) {
                    parts.push_back(seg);
                    self(self, start + len);
                    parts.pop_back();
                }
            }
        };
        backtrack(backtrack, 0);
        return res;
    }
};

class Solution {
    public List<String> restoreIpAddresses(String s) {
        List<String> res = new ArrayList<>();
        backtrack(s, 0, new ArrayList<>(), res);
        return res;
    }

    private void backtrack(String s, int start, List<String> parts, List<String> res) {
        if (parts.size() == 4) {
            if (start == s.length()) {
                res.add(String.join(".", parts));
            }
            return;
        }
        for (int len = 1; len <= 3; len++) {
            if (start + len > s.length()) break;
            String seg = s.substring(start, start + len);
            if (seg.length() > 1 && seg.charAt(0) == '0') continue;
            if (Integer.parseInt(seg) <= 255) {
                parts.add(seg);
                backtrack(s, start + len, parts, res);
                parts.remove(parts.size() - 1);
            }
        }
    }
}

var restoreIpAddresses = function(s) {
    const res = [];
    const parts = [];
    const backtrack = (start) => {
        if (parts.length === 4) {
            if (start === s.length) {
                res.push(parts.join('.'));
            }
            return;
        }
        for (let len = 1; len <= 3; len++) {
            if (start + len > s.length) break;
            const seg = s.slice(start, start + len);
            if (seg.length > 1 && seg[0] === '0') continue;
            if (Number(seg) <= 255) {
                parts.push(seg);
                backtrack(start + len);
                parts.pop();
            }
        }
    };
    backtrack(0);
    return res;
};
